WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, p.ViewCount, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.Score DESC NULLS FIRST) AS rn FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR AND p.Score > 0), PostVoteStats AS (SELECT PostId, COUNT(*) FILTER(WHERE vt.Name = 'UpMod') AS UpvoteCount, COUNT(*) FILTER(WHERE vt.Name = 'DownMod') AS DownvoteCount, COUNT(*) AS TotalVotes FROM Votes AS v JOIN VoteTypes AS vt ON v.VoteTypeId = vt.Id GROUP BY PostId), ClosedPostReasons AS (SELECT ph.PostId, GROUP_CONCAT(cr.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.PostId) SELECT rp.PostId, rp.Title, rp.CreationDate, rp.Score, rp.ViewCount, COALESCE(pvs.UpvoteCount, 0) AS UpvoteCount, COALESCE(pvs.DownvoteCount, 0) AS DownvoteCount, COALESCE(pvs.TotalVotes, 0) AS TotalVotes, COALESCE(cpr.CloseReasons, 'No close reasons') AS CloseReasons FROM RankedPosts AS rp LEFT JOIN PostVoteStats AS pvs ON rp.PostId = pvs.PostId LEFT JOIN ClosedPostReasons AS cpr ON rp.PostId = cpr.PostId WHERE rp.rn = 1 ORDER BY rp.Score DESC NULLS FIRST, rp.CreationDate DESC NULLS FIRST LIMIT 50